function movementControls(u,o){if(M.isClimb(o.moveKind))return '<p class="stagePrompt">点击接触的楼房，自动识别楼高和墙面。攀爬预算为 MOV 第一值 + 2″；完整底盘登顶后立即停止，剩余距离不能走屋顶。</p><p class="helper">普通攀爬须先贴墙。距离墙面 0.5″ 时，应先用另一条命令移动贴墙。再次点击会重新规划本次攀爬。</p>';if(M.isJump(o.moveKind))return `<p class="stagePrompt">${u.jetPropulsion?'喷气推进：允许空中转向。':'普通跳跃：保持水平前进方向，不可空中转向。'} 路线按途经点之间的三维直线距离累计。</p><p class="helper">${o.moveKind==='superjump'?'短超级跳：MOV1＋'+(u.superJumpBonus??u.jumpBonus??2)+'″':u.superJump?'整令超级跳：MOV1＋4″':'普通跳跃整令：MOV1＋'+(u.jumpBonus??2)+'″'}。点击楼顶自动识别高度并规划折线。只指定最终落点时，再次点击替换落点；接触落地表面即结束，后续 Move 另用第二项技能。</p>${u.jetPropulsion?`<label class="field">地图点击用途<select id="jumpPointMode"><option value="landing" ${o.jumpPointMode!=='air'?'selected':''}>最终落点（自动识别楼高）</option><option value="air" ${o.jumpPointMode==='air'?'selected':''}>添加空中途经点（可转向）</option></select></label><label class="field">空中途经点高度<input id="jumpHeight" type="number" min="0" max="48" step="0.1" value="${o.jumpHeight??4}">″</label><button id="jumpRise">在当前途经点垂直升降至此高度</button><p class="helper">先逐点指定空中轨迹，再切回“最终落点”。${o.jumpHasLanding===false?'尚未指定落点，不能确认。':''}</p><ol class="jump-waypoints">${(o.jumpWaypoints||o.path?.slice(0,1)||[]).map((p,i)=>'<li>'+ (i?'空中点':'起点')+'：('+p.x.toFixed(2)+', '+p.y.toFixed(2)+') · Z '+(p.z||0).toFixed(2)+'″</li>').join('')}${o.jumpHasLanding?'<li>落点：Z '+(o.path.at(-1).z||0).toFixed(2)+'″</li>':''}</ol>`:''}`;return surfaceHTML()+(u.climbingPlus?'<label><input id="autoWall" type="checkbox">沿墙移动（强化攀爬，点击楼房自动识别）</label>':'');}
