function stateControls(u,busy){return `<h3>状态与过保训练</h3><p class="helper">伤害和弹药会自动施加状态。以下开关只用于布置教学场景，不是游戏内治疗。孤立后从下一己方回合获得自身不规则命令。</p><label class="field">部队类型<select id="unitType" ${busy?'disabled':''}>${['LI','HI','REM','TAG','VH'].map(k=>`<option ${u.type===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">生命属性<select id="lifeAttribute" ${busy?'disabled':''}>${['VITA','STR'].map(k=>`<option ${u.attribute===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field"><input id="remotePresence" type="checkbox" ${u.remotePresence?'checked':''} ${busy?'disabled':''}>遥控存在（STR 两级昏迷）</label><label class="field">免疫实验<select id="immunity" ${busy?'disabled':''}>${['无','ARM','BTS','Enhanced','Critical','SHOCK','EM'].map(k=>`<option ${((u.immunities||[])[0]||'无')===k?'selected':''}>${k}</option>`).join('')}</select></label><div class="statusChecks">${['immA','immB','isolated','stunned','targeted'].map(k=>`<label><input data-state="${k}" type="checkbox" ${S.has(u,k)?'checked':''} ${busy?'disabled':''}>${S.LABELS[k]}</label>`).join('')}</div>`;}
function bindStateControls(u){for(const [id,key] of [['unitType','type'],['lifeAttribute','attribute']])$(id).onchange=e=>{checkpoint();u[key]=e.target.value;S.health(u);render();};$('remotePresence').onchange=e=>{checkpoint();u.remotePresence=e.target.checked;S.health(u);render();};$('immunity').onchange=e=>{checkpoint();u.immunities=e.target.value==='无'?[]:[e.target.value];render();};document.querySelectorAll('[data-state]').forEach(el=>el.onchange=()=>{checkpoint();u.states=(u.states||[]).filter(k=>k!==el.dataset.state);if(el.checked)u.states.push(el.dataset.state);if(el.checked&&el.dataset.state==='isolated'){u.ftLevel=0;u.irregular=0;}render();});}

function openStateAtlas(){const u=selected(),el=$('stateAtlas');$('stateAtlasContent').innerHTML=T.atlasHTML(u,state.units,!!state.order);const search=$('stateSearch');search.oninput=()=>{const q=search.value.trim().toLowerCase();el.querySelectorAll('[data-state-search]').forEach(card=>card.hidden=!card.dataset.stateSearch.includes(q));};el.querySelectorAll('[data-annotate]').forEach(button=>button.onclick=()=>{if(state.order)return;const key=button.dataset.annotate;checkpoint();u.displayStates=u.displayStates||[];u.displayStates=u.displayStates.includes(key)?u.displayStates.filter(k=>k!==key):[...u.displayStates,key];const query=search.value;render();openStateAtlas();$('stateSearch').value=query;$('stateSearch').oninput();});el.querySelectorAll('[data-token-variant]').forEach(select=>select.onchange=()=>{if(state.order)return;u.tokenVariants={...(u.tokenVariants||{}),[select.dataset.tokenVariant]:+select.value};render();});if(!el.open)el.showModal();}

function bindSkillControls(u){
 $('unitDetail').querySelectorAll('[data-skill]').forEach(el=>el.onchange=()=>{checkpoint();u[el.dataset.skill]=el.checked;if(el.dataset.skill==='tacticalAwareness')u.tacticalOrders=el.checked?1:0;render();});
 $('unitDetail').querySelectorAll('[data-skill-number]').forEach(el=>el.onchange=()=>{checkpoint();u[el.dataset.skillNumber]=E.clamp(+el.value,+el.min,+el.max);render();});
 if($('toggleCamo'))$('toggleCamo').onclick=()=>{checkpoint();if(K.marker(u))K.reveal(u);else K.enterCamo(u);render();};
}
function discoverTargetsHTML(id){const u=selected();return `<label class="field">发现目标<select id="${id}">${state.units.filter(v=>v.team!==u.team&&(K.marker(v)||K.masked(v))).map(v=>`<option value="${v.id}">${v.name} · CAMO</option>`).join('')||'<option value="">没有迷彩标记</option>'}</select></label>`;}
function discoverReaction(v,r){if(!(K.marker(selected())||K.masked(selected()))||!r.lof)return null;let best=null;for(const p of E.samplePath(declaredPath(),.15)){const spec=K.discoverSpec(v,{...selected(),...p},terrain,{turn:K.turnKey(state)});if(spec.can&&(!best||spec.sv>best.spec.sv))best={spec,point:p};}return best;}
function utilityControls(){const u=selected();return `<details open><summary>发现与任务技能</summary>${discoverTargetsHTML('utilityTarget')}<div class="buttonpair"><button id="secondDiscover">发现 Discover</button>${u.sensor&&!o.impetuous?'<button id="sensorAction">Sensor · 8″区域</button>':''}</div>${missionActionHTML()||''}</details>`;}
function bindUtilityControls(){
 if($('secondDiscover'))$('secondDiscover').onclick=()=>{const u=selected(),v=state.units.find(n=>n.id===$('utilityTarget').value);if(!v)return;const spec=K.discoverSpec(attackOrigin(),v,terrain,{moving:E.pathLength(declaredPath())>0,turn:K.turnKey(state)});if(!spec.can){toast(spec.reason);return;}if(state.order.discoveries?.some(d=>d.targetId===v.id&&d.observerId===u.id)){toast('同一命令不能对同一目标发现两次');return;}state.order.discoveries??=[];state.order.discoveries.push({observerId:u.id,targetId:v.id,point:{...attackOrigin()},moving:E.pathLength(declaredPath())>0});declareUtility('discover');};
 if($('sensorAction'))$('sensorAction').onclick=()=>{const o=state.order,u=selected();o.sensor=true;declareUtility('sensor');};
}
function skillTasks(){const o=state.order,u=selected(),tasks=[];
 for(const d of o.discoveries||[]){const a=state.units.find(n=>n.id===d.observerId),b=state.units.find(n=>n.id===d.targetId);if(!b)continue;const spec=K.discoverSpec({...a,...d.point},b,terrain,{moving:!!d.moving,turn:K.turnKey(state)});tasks.push({kind:'discover',observerId:a.id,targetId:b.id,name:a.name,team:a.team,targetName:b.name,label:'发现 Discover',sv:spec.can?spec.sv:0,automatic:!K.marker(b)||(spec.can&&spec.automatic),modText:spec.can?spec.mods.filter(m=>m[1]).map(m=>m.join(' ')).join(' / '):spec.reason});}
 for(const r of Object.values(o.reactions).filter(r=>r.action==='discover')){const a=state.units.find(n=>n.id===r.id),b={...u,...r.point};const spec=K.discoverSpec(a,b,terrain,{turn:K.turnKey(state)});tasks.push({kind:'discover',observerId:a.id,targetId:u.id,name:a.name,team:a.team,targetName:u.name,label:'ARO 发现',sv:spec.can?spec.sv:0,automatic:!K.marker(u)||(spec.can&&spec.automatic),modText:spec.mods.filter(m=>m[1]).map(m=>m.join(' ')).join(' / ')});}
 if(o.sensor)for(const b of state.units.filter(b=>b.team!==u.team&&(K.marker(b)||S.has(b,'hiddenDeployment'))&&H.inZone(u,b))){const spec=K.discoverSpec(u,b,terrain,{sensor:true});tasks.push({kind:'sensor',observerId:u.id,targetId:b.id,name:u.name,team:u.team,targetName:b.name,label:'Sensor · WIP+6',sv:spec.sv,group:'sensor'});}
 if(o.sensor&&!tasks.some(t=>t.kind==='sensor'))tasks.push({kind:'sensor',observerId:u.id,name:u.name,team:u.team,targetName:'8″ 区域',label:'Sensor · WIP+6',sv:(u.wip||13)+6,group:'sensor'});return tasks.concat(missionRollTasks()||[],supportTasks(),zoneSkillTasks());
}
function openSkillRolls(){const o=state.order;skillRollDialog(o,skillTasks(),{save,rerollOptions:supportRerolls,onReroll:(t,r)=>{if(r.id==='skill')t.skillUsed=true;else state.commandTokens[t.team]-=r.cost;},roll:()=>1+Math.floor(teachingRng()()*20),onComplete:rows=>{for(const t of rows){const a=state.units.find(n=>n.id===t.observerId),b=state.units.find(n=>n.id===t.targetId);if(t.kind==='discover'||t.kind==='sensor'){if(t.success&&b){DX.cancelDecoys(state,b,'discovered');K.reveal(b);}else if(t.kind==='discover'){a.discoverFailures??={};a.discoverFailures[K.markerKey(b)]=K.turnKey(state);}}else if(t.kind==='zoneSkill')applyZoneSkill(t);else if(t.kind==='support')applySupportRoll(t);else applyMissionRoll(t);log(`${t.name} ${t.label} → ${t.targetName}：${t.skipped?'待机（要求未满足）':t.success?'成功':'失败'}。`);}o.skillsApplied=true;if(!o.idle&&K.marker(enemy())&&selected().msv!==3){o.idle=true;o.activeSkill='discover';log('发现未成功：原定对该迷彩的攻击不能执行，按待机处理。');}save();startDice();}});}
$('skillAtlasBtn').onclick=()=>{$('skillAtlasContent').innerHTML=catalogHTML(skillCatalog);$('skillAtlas').showModal();$('skillSearch').oninput=e=>{const q=e.target.value.toLowerCase();$('skillAtlasContent').querySelectorAll('[data-skill-search]').forEach(n=>n.hidden=!n.dataset.skillSearch.includes(q));};};
$('closeSkillAtlas').onclick=()=>$('skillAtlas').close();


function missionMap(){Q.syncBeacons(state);return state.objectives.map(o=>`<g><circle cx="${o.x}" cy="${o.y}" r="${o.r}" fill="#111423" stroke="${o.kind==='console'?(o.owner===null?'#d6c3ff':C[o.owner]):C[o.team]}" stroke-width=".14"/>${text(o.x,o.y+.15,o.kind==='console'?'C':'B',.5,'#fff','text-anchor="middle"')}${text(o.x,o.y-o.r-.4,o.name,.42,'#e9ddff','text-anchor="middle"')}</g>`).join('')+state.hvts.map(h=>`<circle cx="${h.x}" cy="${h.y}" r="${E.radius(h)}" fill="#231c32" stroke="#d9c8ff" stroke-width=".13"/>${text(h.x,h.y+1,h.name,.42,'#d9c8ff','text-anchor="middle"')}`).join('');}
function missionPanelHTML(){if(state.missionId==='annihilation'){const v=Q.annihilationValues(state);return `<div class="missionPanel"><b>ANNIHILATION · 歼灭战</b> <a href="${Q.MISSIONS.annihilation.source}" target="_blank" rel="noreferrer">官方任务 ↗</a><p>300点级：击杀敌军点数及己方存活点数各计0–4分（75–150：1分，151–250：3分，超过250：4分）；击杀敌尉官2分。无HVT／机密任务，不执行Retreat，三轮结束。</p><p>红方已击杀 ${v[1].killed} 点 · 存活 ${v[0].surviving} 点；蓝方已击杀 ${v[0].killed} 点 · 存活 ${v[1].surviving} 点。</p><p>局中为预估；终局Null及仍未部署模型计为被击杀。特殊任务加减分争议以官方裁定为准。</p></div>`;}return `<div class="missionPanel"><b>HARDLOCK · 信标封锁</b> <a href="${Q.SOURCE}" target="_blank" rel="noreferrer">官方任务 ↗</a><p>每轮控制敌信标 1 分；终局：保住己方信标 1 分，控制台更多 2 分，每个己方控制台 1 分，机密 1 分。满分 10。</p><div class="missionTargets">${state.objectives.map(o=>`<span>${o.name} · ${o.kind==='console'?(o.owner===null?'未激活':o.owner?'蓝方':'红方'):(o.carrier?'携带中':'地面')}</span>`).join('')}</div><p>逐轮已锁定：${Object.entries(state.roundScores).map(([r,p])=>`R${r} 红${p[0]} / 蓝${p[1]}`).join('；')||'尚未结算'}。上方得分包含终局预估。</p><details><summary>HVT 与机密任务（每方 1 项）</summary><p>HVT 中立、不参与命令或 ARO。现行实体 Operations Deck 抽两张后录入，选择一张保密；完成条件依实体卡裁定。这里不是完整自动机密牌库。</p>${[0,1].map(t=>{const c=state.classified[t];return `<div class="classified team-${t}"><b>${t?'◆ 蓝方':'▲ 红方'} · ${c.done?'已公开：'+safeText(c.selected):c.selected?'机密已选择 · 隐藏':'尚未选择'}</b><details><summary>本人查看 / 管理机密</summary>${c.selected?`<p>${safeText(c.selected)}</p><button data-complete-card="${t}" ${c.done?'disabled':''}>展示并记录达成（人工裁定）</button>`:`<label>实体抽牌 1<input id="card${t}a" maxlength="100"></label><label>实体抽牌 2<input id="card${t}b" maxlength="100"></label><button data-pick-card="${t}:a">保留第一张</button><button data-pick-card="${t}:b">保留第二张</button>`}<button data-secure="${t}" ${state.phase!=='finished'||c.done?'disabled':''}>终局改用 Secure HVT</button><p>当前 Secure HVT 条件：${Q.secureHVT(state,t)?'满足':'未满足'}${c.secure?' · 已选择替换':''}</p></details></div>`;}).join('')}<p>共享屏幕教学模式不提供真正的账户级私密隔离。</p></details></div>`;}
function bindMissionPanel(){if(state.order){document.querySelectorAll('.missionPanel button').forEach(b=>b.disabled=true);return;}document.querySelectorAll('[data-pick-card]').forEach(b=>b.onclick=()=>{const [t,k]=b.dataset.pickCard.split(':'),a=$('card'+t+'a').value.trim(),c=$('card'+t+'b').value.trim();if(!a||!c){toast('请录入从当前实体牌组抽出的两张牌');return;}checkpoint();state.classified[t]={selected:k==='a'?a:c};render();});document.querySelectorAll('[data-complete-card]').forEach(b=>b.onclick=()=>{checkpoint();const c=state.classified[+b.dataset.completeCard];c.done=true;c.secure=false;log('机密公开并由玩家确认达成：'+safeText(c.selected));render();});document.querySelectorAll('[data-secure]').forEach(b=>b.onclick=()=>{if(state.phase!=='finished')return;checkpoint();state.classified[+b.dataset.secure].secure=true;render();});}
function missionActionHTML(){if(state.missionId==='annihilation')return '<p>此任务没有控制台或信标交互目标。</p>';const u=selected();return `<label class="field">任务目标<select id="missionTarget">${state.objectives.map(o=>`<option value="${o.id}">${o.name}</option>`).join('')}</select></label><div class="buttonpair"><button id="activateConsole">激活控制台 · WIP</button><button id="pickupBeacon">拿取敌信标</button></div><p class="micro">控制台仅专家接触后激活；拿信标须己方至少激活一个控制台。</p>`;}
function bindMissionActions(){if($('activateConsole'))$('activateConsole').onclick=()=>{const obj=state.objectives.find(o=>o.id===$('missionTarget').value);if(!Q.activationSpec(selected(),obj).can){toast('需要专家接触控制台，且状态允许攻击技能');return;}state.order.objective=obj.id;declareUtility('objective');};if($('pickupBeacon'))$('pickupBeacon').onclick=()=>{const obj=state.objectives.find(o=>o.id===$('missionTarget').value),err=Q.pickupError(state,selected(),obj);if(err){toast(err);return;}state.order.pickup=obj.id;declareUtility('objective');};}
function missionRollTasks(){const o=state.order,u=selected(),obj=state.objectives.find(v=>v.id===o.objective);if(!obj)return [];const spec=Q.activationSpec(u,obj);return [{kind:'objective',observerId:u.id,targetId:obj.id,name:u.name,team:u.team,targetName:obj.name,label:'激活控制台',sv:spec.can?spec.sv:0,sd:0}];}
function applyMissionRoll(t){const u=state.units.find(u=>u.id===t.observerId),o=state.objectives.find(o=>o.id===t.targetId);if(o)Q.activate(state,u,o,t.success);}

function placementPoint(p,noSnap=false){const u=selected(),o=state.order,raw={...p,z:+(state.surface||0),wall:null};
 if(state.phase==='deploy')return snapToCover(u,raw,terrain,{enabled:state.coverSnap!==false&&!noSnap,valid:q=>!Q.deploymentError(u,q,state.units,terrain,state.objectives)});
 if(o?.step!=='move'||M.isJump(o.moveKind)||M.isClimb(o.moveKind)||o.moveKind==='idle')return {point:raw,terrainId:null};
 const passage=state.coverSnap!==false&&!noSnap&&M.snapPassage(u,raw,terrain);if(passage)return {point:passage,terrainId:'窄道'};
 return snapToCover(u,raw,terrain,{enabled:state.coverSnap!==false&&!noSnap,valid:q=>{const last=o.path.at(-1),segment=M.moveSegment(u,last,q,terrain);if(segment.error)return false;return !M.validate(u,{...o,path:[...o.path,...segment.points.slice(1)],cost:(o.cost||0)+segment.cost},state.units,terrain,false);}});
}

function orderSourceHTML(u){return `<label class="field">命令来源<select id="orderSource">${O.sources(state,u).map(([k,t])=>`<option value="${k}">${t}</option>`).join('')}</select></label>`;}
function renderOrderHUD(){let field=$('terrainAreaType');if(!field){const label=document.createElement('label');label.className='field';label.innerHTML='困难地形区域（赛前约定）<select id="terrainAreaType"><option value="">无</option>'+Object.entries(TR.TYPES).map(([k,v])=>'<option value="'+k+'">中心区域 · '+v+'</option>').join('')+'</select>';document.querySelector('#heightLegend').after(label);field=$('terrainAreaType');field.onchange=()=>{if(state.phase==='play'||state.order)return;state.terrainAreas=field.value?[{x:14,y:18,w:12,h:12,type:field.value}]:[];render();};}field.disabled=state.phase==='play'||!!state.order;field.value=state.terrainAreas?.[0]?.type||'';let el=$('orderHUD');if(!el){el=document.createElement('div');el.id='orderHUD';el.className='orderHUD';document.querySelector('.workspace').prepend(el);}el.innerHTML=`<span class="diceMode ${state.fixedDice?'fixed':''}">${state.fixedDice?'固定教学骰例':'随机掷骰'}</span>`+[0,1].map(t=>`<div class="team-${t} ${state.team===t?'current':''}"><span>${t?'◆ 蓝队':'▲ 红队'}${state.team===t?' · 当前回合':''}</span>${Object.entries(O.pools(state,t)).map(([g,n])=>`<b class="groupPool ${selected().team===t&&O.group(selected())===+g?'selectedGroup':''}">G${g} 正规 ${n}</b>`).join('')}<b>尉官 ${state.lieutenantOrders?.[t]||0}</b><small>指挥令 ${state.commandTokens?.[t]??4}</small></div>`).join('');}
function postureHTML(u,id,value='keep'){if(!S.canProne(u))return '';return `<label class="field">移动姿态<select id="${id}"><option value="keep" ${value==='keep'?'selected':''}>保持${u.prone?'俯卧（距离减半）':'站立'}</option>${(u.prone?['standStart','standEnd']:['proneStart','proneEnd']).map((v,i)=>`<option value="${v}" ${v===value?'selected':''}>${i?'终点':'起点'}${u.prone?'起身':'俯卧'}${(u.prone?i:!i)?'（移动距离减半）':''}</option>`).join('')}</select></label>`;}
function dodger(){return state.units.find(u=>u.id===state.order?.dodgers?.[0]);}
function initDodge(){const o=state.order,v=dodger();o.dodgeFacing=v.facing;o.dodgePlan={moveKind:'move',path:[{x:v.x,y:v.y,z:v.z||0,wall:v.wall||null}],cost:0,distance:K.dodgeDistance(v),stance:'keep'};}
function dodgeSegment(p,noSnap=false){const v=dodger(),plan=state.order.dodgePlan,last=plan.path.at(-1);if(v.climbingPlus&&$('dodgeAutoWall')?.checked){const climb=M.autoClimb({...v,...last},p,M.budget(v,plan)-plan.cost,terrain,state.units);return climb.error?climb:{plan:{...plan,path:[...plan.path,...climb.points.slice(1)],cost:plan.cost+climb.cost}};}const next=M.nearestReachable(v,plan,{...p,z:last.z||0},state.units,terrain);return next.error?next:{plan:{...plan,path:next.path,cost:next.cost}};}
function addDodgePoint(p,noSnap){const seg=dodgeSegment(p,noSnap);if(seg.error){toast(seg.error);return;}state.order.dodgePlan=seg.plan;render();}
function postMoveMap(){const o=state.order;if(!o)return '';let s='';if(['aro1','aro2'].includes(o.step)){for(const r of Object.values(o.reactions)){if(r.action)continue;const v=state.units.find(v=>v.id===r.id),c=reactionChoices(v,r).find(c=>c.value===r.draft);if(!c||F.weaponMode(c.key,c.modeId).kind!=='direct')continue;const aim=r.aim||c.points[0],a=Math.atan2(aim.y-v.y,aim.x-v.x),tip={x:v.x+(E.radius(v)+2)*Math.cos(a),y:v.y+(E.radius(v)+2)*Math.sin(a)};s+=line(v,tip,'#ffc247')+`<circle cx="${tip.x}" cy="${tip.y}" r=".18" fill="#ffc247"/>`+text(v.x,v.y-E.radius(v)-1.3,'喷射方向 · 未量范围',.45,'#ffc247','text-anchor="middle"');}}if(o.step==='dodge'){const v=dodger(),plan=o.dodgePlan,r=E.radius(v);s+=`<circle cx="${v.x}" cy="${v.y}" r="${E.movementBudget(v,o.dodgePlan.stance,K.dodgeDistance(v))}" fill="#9bf5c5" fill-opacity=".06" stroke="#9bf5c5" stroke-width=".12" stroke-dasharray=".2 .15"/>`;for(let i=1;i<plan.path.length;i++)s+=line(plan.path[i-1],plan.path[i],'#b9ffcf');const last=plan.path.at(-1);s+=`<circle cx="${last.x}" cy="${last.y}" r="${r}" fill="#9bf5c5" fill-opacity=".2" stroke="#b9ffcf" stroke-width=".13"/>`+text(v.x,v.y-r-1.3,'闪避移动 '+plan.cost.toFixed(2)+'″',.65,'#b9ffcf','text-anchor="middle"');if(hover){const seg=dodgeSegment(hover);if(!seg.error)s+=line(last,seg.plan.path.at(-1),'#b9ffcf','.2 .15');}}if(o.step==='guts'&&o.guts[0]?.failed){const path=o.guts[0].plan?.path||[];for(let i=1;i<path.length;i++)s+=line(path[i-1],path[i],'#ffc247');for(const c of o.guts[0].options||[])s+=`<circle cx="${c.point.x}" cy="${c.point.y}" r=".10" fill="#ffe29a"/>`;}for(const r of Object.values(o.reactions||{})){if(!r.shape)continue;const sh=r.shape;s+=sh.kind==='circle'?`<circle cx="${sh.origin.x}" cy="${sh.origin.y}" r="${sh.r}" fill="#b0a1ff" fill-opacity=".12" stroke="#cdbfff" stroke-width=".08"/>`:`<polygon points="${sh.poly.map(p=>p.x+','+p.y).join(' ')}" fill="#b0a1ff" fill-opacity=".12" stroke="#cdbfff" stroke-width=".08"/>`;}return s;}
function advanceGuts(){const o=state.order;o.guts=(o.guts||[]).filter(g=>{const u=state.units.find(u=>u.id===g.id);return S.active(u)&&!S.has(u,'immA')&&!S.has(u,'immB')&&!G.engaged(u,state.units);});if(!o.guts.length){completeDeployments();return;}o.step='guts';const g=o.guts[0],u=state.units.find(u=>u.id===g.id);if(S.has(u,'stunned')&&!u.courage&&!u.religious){g.failed=true;g.result='眩晕：自动失败';prepareGutsMove(g,u);}}
function prepareGutsMove(g,u){EQ.cancelSuppressive(u);g.stance??='keep';g.facing??=u.facing;g.options=G.options(u,g.attackers,state.units,terrain,state.objectives,g.stance);g.manualPath=[{x:u.x,y:u.y,z:u.z||0}];g.plan=null;}
function gutsHTML(){const g=state.order.guts[0],u=state.units.find(u=>u.id===g.id);return `<h3 class="paneltitle">⑦ 勇气阶段 · ${u.name}</h3><p class="helper">承受成功攻击后仍可行动：WIP ${u.wip}。按攻击者实际开火位置判定；本阶段不消耗命令、不触发 ARO。</p>${g.result?`<p class="gutsResult ${g.rolling?'rolling':''}">${g.result}</p>`:''}${g.failed?`${postureHTML(u,'gutsStance',g.stance)}<label class="field">结束朝向<input id="gutsFacing" type="range" min="-180" max="180" value="${g.facing??u.facing}"></label><p>失败：${g.options.length?(g.options[0].tier===1?'离开全部攻击者视线':'取得对全部攻击者的掩体')+'。点击地图金色候选点，最多 2″。':'没有找到推荐撤离点。可点击地图规划合法路线，或确认无可行路线后俯卧。'}</p><p class="micro">候选路线包含直线及绕墙角；推荐点不代表全部合法路线；先离开全部攻击者视线，否则争取掩体。</p>${g.plan?`<p class="stagePrompt">已规划 ${g.plan.cost.toFixed(2)}″ / ${E.movementBudget(u,g.stance,2)}″</p><button id="confirmGutsMove" class="primary wide">确认败勇气移动</button>`:''}<button id="clearGutsMove" class="wide">清除撤离路线</button>${!g.options.length?'<button id="gutsProne" class="primary wide">确认无合法撤离路线 → 俯卧／留在原地</button>':''}`:g.result?`<button id="gutsNext" class="primary wide" ${g.rolling?'disabled':''}>确认结果 → ${g.withdraw?'选择撤离':'保持位置'}</button>`:`<button id="rollGuts" class="primary wide">${u.religious?'申请撤离 · WIP 检定':'勇气检定 · 掷 WIP 骰'}</button>${u.courage||u.religious?'<button id="passGuts" class="wide">自动成功 · 坚守</button>':''}${!u.religious?'<button id="failGuts" class="wide">选择自动失败 · 寻找掩体</button>':''}`}`;}
function finishGuts(){state.order.guts.shift();advanceGuts();render();}
function chooseGutsPoint(p){const g=state.order.guts[0];if(!g.failed)return;const u=state.units.find(u=>u.id===g.id);if(G.tier(u,u,g.attackers,terrain)===1){toast('已经离开攻击视线／危险区：败勇气时应俯卧');return;}const c=g.options.length?g.options.reduce((a,b)=>E.dist(a.point,p)<E.dist(b.point,p)?a:b):null;if(c&&E.dist(c.point,p)<=.5){g.plan={path:c.path,cost:c.path.slice(1).reduce((n,q,i)=>n+E.dist(q,c.path[i]),0),end:c.point};}else{const path=g.plan?.path||g.manualPath,cost=g.plan?.cost||0,plan=M.nearestReachable(u,{moveKind:'move',path,cost,distance:2,stance:g.stance},{...p,z:u.z||0},state.units,terrain);if(plan.error){toast(plan.error);return;}const err=G.legalPath(u,plan.path,state.units,terrain,state.objectives,g.stance);if(err){toast(err);return;}g.plan=plan;}render();}
function confirmGutsMove(){const g=state.order.guts[0],u=state.units.find(u=>u.id===g.id),p=g.plan;if(!p)return;const bad=G.legalPath(u,p.path,state.units,terrain,state.objectives,g.stance),tier=G.tier(u,p.end,g.attackers,terrain,g.stance);if(bad||!tier){toast(bad||'终点必须脱离全部攻击视线／危险区，或取得掩体');return;}if(tier===2&&g.options.some(c=>c.tier===1)){toast('存在可离开全部视线的路线，必须优先撤离');return;}Object.assign(u,p.end,{prone:E.endingProne(u,g.stance),facing:g.facing});log(u.name+' 败勇气移动 '+p.cost.toFixed(2)+'″');finishGuts();}
function bindPostControls(){const o=state.order;if($('confirmGutsMove'))$('confirmGutsMove').onclick=confirmGutsMove;if($('clearGutsMove'))$('clearGutsMove').onclick=()=>{prepareGutsMove(o.guts[0],state.units.find(u=>u.id===o.guts[0].id));render();};if($('dodgeStance'))$('dodgeStance').onchange=e=>{const stance=e.target.value;initDodge();o.dodgePlan.stance=stance;render();};if($('gutsStance'))$('gutsStance').onchange=e=>{const g=o.guts[0];g.stance=e.target.value;prepareGutsMove(g,state.units.find(u=>u.id===g.id));render();};if($('gutsFacing'))$('gutsFacing').oninput=e=>{o.guts[0].facing=+e.target.value;};if($('clearDodge'))$('clearDodge').onclick=()=>{initDodge();render();};if($('dodgeFacing'))$('dodgeFacing').oninput=e=>{o.dodgeFacing=+e.target.value;save();};if($('confirmDodge'))$('confirmDodge').onclick=()=>{const v=dodger(),bad=M.validate(v,o.dodgePlan,state.units,terrain);if(bad){toast(bad);return;}Object.assign(v,o.dodgePlan.path.at(-1),{facing:o.dodgeFacing,prone:E.endingProne(v,o.dodgePlan.stance)});log(`${v.name} 闪避移动 ${o.dodgePlan.cost.toFixed(2)}″。`);finishDodge();};if(o?.step!=='guts')return;const g=o.guts[0],u=state.units.find(u=>u.id===g.id);if($('passGuts'))$('passGuts').onclick=()=>{log(u.name+' 勇气自动成功，坚守。');finishGuts();};if($('failGuts'))$('failGuts').onclick=()=>{g.failed=true;g.result='选择自动失败';prepareGutsMove(g,u);render();};if($('rollGuts'))$('rollGuts').onclick=()=>{g.die=1+Math.floor(teachingRng()()*20);const success=g.die<=u.wip;g.withdraw=u.religious?success:!success;g.result=`d20 = ${g.die} / WIP ${u.wip} · ${g.withdraw?'须寻找掩体':'坚守'}`;g.rolling=true;log(u.name+' 勇气：'+g.result);save();render();setTimeout(()=>{if(state.order?.guts?.[0]!==g)return;g.rolling=false;render();},900);};if($('gutsNext'))$('gutsNext').onclick=()=>{if(g.withdraw){g.failed=true;prepareGutsMove(g,u);render();}else finishGuts();};if($('gutsProne'))$('gutsProne').onclick=()=>{if(S.canProne(u)&&!u.impetuous)u.prone=true;u.facing=g.facing??u.facing;log(u.name+' 勇气失败：'+(u.prone?'俯卧':'不能俯卧，留在原地'));finishGuts();};}

// N5 support actions: declarations are stored separately from attacks.
function chargeKey(u){return D.available(u).find(k=>F.ARMS[k]?.demolition);}
function demolitionTarget(v){return S.onTable(v)&&!S.has(v,'possessed')&&!S.has(v,'sepsitorized')&&(!S.active(v)||S.has(v,'immA')||S.has(v,'immB'));}
function utilityAvailable(u,reactive=false,r=null){
 if(state.order?.impetuous||u.isDeployable||u.wall&&!u.climbingPlus)return [];if(G.engaged(u,state.units))return !reactive&&chargeKey(u)&&S.allowed(u,'attack')?['demolition']:[];
 const out=[...U.availableActions(u,{reactive}),...X.availableActions(u,{reactive}).filter(k=>k!=='forwardObserver')];
 if(D.available(u,{deployableOnly:true}).some(id=>D.declaration(u,id,{reactive,lof:r?.lof}).can))out.push('deployable');
 if(D.canReload(u,state.units,{measure:false}).can)out.push('reload');
 if(!reactive&&H.supportActions(u).some(p=>p.skill==='short'&&p.id!=='zeroPain'))out.push('supportware');if(!reactive&&H.supportActions(u).some(p=>p.id==='zeroPain'))out.push('zeroPain');
 if(!reactive&&Z.whiteNoiseAvailable(u))out.push('whiteNoise');
 if(!reactive&&Z.available(u).length)out.push('targetless');
 if(!reactive&&chargeKey(u)&&S.allowed(u,'attack'))out.push('demolition');
 if(!reactive&&u.deactivator&&S.allowed(u,'attack'))out.push('activateBall');
 return out;
}
function supportOptions(u,kind){return state.units.filter(v=>!v.isDeployable).flatMap(v=>U.modes(u,v,kind).map(m=>({value:v.id+':'+m.id,target:v,mode:m})));}
function supportControls(kind){if(kind==='demolition'){const targets=state.units.filter(v=>v.team!==selected().team&&demolitionTarget(v));return '<h3>爆破装药 · 主动短技能（不能 ARO）</h3><button id="backToSkills">← 返回行动选择</button><label>接触目标<select id="demolitionTarget">'+targets.map(v=>'<option value="'+v.id+'">'+safeText(v.name)+'</option>').join('')+terrain.filter(t=>t.kind==='building').map(t=>'<option value="terrain:'+t.id+'">'+safeText(t.name)+' · 当前任务无可破坏属性</option>').join('')+'</select></label><p>对 IMM／Null 敌方模型（不含占据、转化）或建筑使用；结算自动命中，PS6、AP+EXP 三次过保。不伤使用者；与近战模式共享三次库存。当前 Hardlock 普通建筑未规定可破坏属性，不会擅自移除。</p><button id="declareSupport" class="primary wide">宣告爆破 · 消耗一次装药</button>';}if(kind==='supportware')return hackingSupportControls();if(['medikit','gizmokit','deactivator'].includes(kind))return extraControls(kind);if(kind==='whiteNoise')return whiteNoiseControls();if(kind==='targetless')return targetlessControls();if(kind==='activateBall')return activateBallControls();const u=selected(),o=state.order,first=M.isLong(o.firstKind);let h=`<h3 class="paneltitle">主动轮${first?'首项':'第二项'}行动 · ${ACTION_NAMES[kind]}</h3>${!first?'<button id="backToSkills" class="wide">← 返回行动选择</button>':''}`;
 if(['doctor','engineer'].includes(kind)){const opts=supportOptions(u,kind);h+=`<label class="field">目标与方式<select id="supportTarget">${opts.map(v=>`<option value="${v.value}" ${o.supportChoice===v.value?'selected':''}>${safeText(v.target.name)} · ${v.mode.name}</option>`).join('')||'<option value="">没有符合条件的目标</option>'}</select></label><p class="helper">必须在行动所选位置接触目标；自身使用仅限规则允许的情况。治疗／修复检定与敌方攻击独立，恢复先于同令伤害生效。</p>${!first?'<label class="field">沿路使用位置<input id="supportPoint" type="range" min="0" max="'+(E.samplePath(declaredPath(),.15).length-1)+'" value="'+o.shotIndex+'"></label>':''}<button id="declareSupport" class="primary wide" ${opts.length?'':'disabled'}>宣告${ACTION_NAMES[kind]}</button>`;}
 if(kind==='deployable'){h+=`<label class="field">携带的部署物<select id="deployItem">${D.available(u,{deployableOnly:true}).filter(id=>!o.intuitive||D.isMine(id)).map(id=>`<option value="${id}" ${o.deployItem===id?'selected':''}>${D.ITEMS[id].name} · 剩余 ${D.remaining(u,id)}</option>`).join('')}</select></label><p class="stagePrompt">点击地图选放置位置，然后确认宣告。普通部署物须接触本人或移动路线；Perimeter 炮塔可放在本人控制区内的可达位置。命令结束才生效。</p>${surfaceHTML()}<p>${o.deployPoint?'已指定位置（确认后检查要求）':'尚未指定落点'}</p><button id="declareSupport" class="primary wide" ${o.deployPoint?'':'disabled'}>宣告放置 · 消耗 1 次使用</button>`;}
 if(kind==='reload'&&!first)h+='<label class="field">沿路装填位置<input id="supportPoint" type="range" min="0" max="'+(E.samplePath(declaredPath(),.15).length-1)+'" value="'+o.shotIndex+'"></label>';if(kind==='reload')h+='<p class="helper">装填者须在非空状态友方辎重的控制区内，结算时检查。恢复携带装备的所有可补充次数；不可装填装备除外。每条命令每方只能让一个单位获得补给。</p><button id="declareSupport" class="primary wide">宣告装填 · 无需掷骰</button>';
 return h;
}
function declareSupport(){const o=state.order,u=selected(),kind=o.utilityKind;if(!utilityAvailable(u).includes(kind)){toast('此单位当前不能使用该行动');return;}
 const declaration={declarationUnits:state.units.map(v=>({id:v.id,x:v.x,y:v.y,z:v.z||0})),kind,actorId:u.id,actorPoint:structuredClone(attackOrigin()),reactive:false};
 if(['medikit','gizmokit','deactivator'].includes(kind)){const v=state.units.find(v=>v.id===$('extraTarget').value),mode=$('extraMode')?.value||'ranged',check=X.validate(declaration.actorPoint,v,kind,{mode,terrain,measure:false});if(!check.can){toast(check.reason);return;}Object.assign(declaration,{targetId:v.id,mode});}
 if(['doctor','engineer'].includes(kind)){const value=$('supportTarget').value,[targetId,mode]=value.split(':'),v=state.units.find(n=>n.id===targetId),check=U.spec(declaration.actorPoint,v,kind,mode,{measure:false});if(!check.can){toast(check.reason);return;}Object.assign(declaration,{targetId,mode});}
 if(kind==='demolition'){declaration.targetId=$('demolitionTarget').value;declaration.weapon=chargeKey(u);if(!declaration.targetId||!declaration.weapon)return;Object.assign(u,D.consume(u,declaration.weapon,{token:o.orderId+':active'}).unit);}
 if(kind==='deployable'){declaration.itemId=$('deployItem').value;declaration.point=o.deployPoint;declaration.intuitive=!!o.intuitive;if(!declaration.point)return;const consumed=D.consume(u,declaration.itemId,{token:o.orderId+':active'});if(consumed.error){toast(consumed.error);return;}Object.assign(u,consumed.unit);}
 if(kind==='reload'&&(o.supports||[]).some(d=>d.kind==='reload'&&state.units.find(v=>v.id===d.actorId).team===u.team)){toast('本命令已有友方单位宣告装填');return;}
 o.supports??=[];o.supports.push(declaration);o.idle=true;o.activeSkill=kind;K.reveal(u);shape=null;target=null;o.target=null;
 collectReactions(M.isLong(o.firstKind)?1:2);o.step=M.isLong(o.firstKind)?'aro1':'aro2';render();
}
function supportTasks(){return (state.order.supports||[]).filter(d=>['doctor','engineer'].includes(d.kind)).map((d,i)=>{const actor=state.units.find(v=>v.id===d.actorId),a={...actor,...d.actorPoint},v=state.units.find(v=>v.id===d.targetId),spec=U.spec(a,v,d.kind,d.mode);return {kind:'support',support:d,observerId:actor.id,targetId:v.id,name:actor.name,team:actor.team,targetName:v.name,label:ACTION_NAMES[d.kind]+' · '+({heal:'救治昏迷',repair:'修复损伤',states:'解除状态'})[d.mode],sv:spec.can?spec.sv:0,valid:spec.can,skipped:!spec.can,modText:spec.can?'普通 WIP 检定，不与敌方攻击拼骰':spec.reason};});}
function supportRerolls(t){if(t.kind!=='support'||!t.valid)return [];const a=state.units.find(v=>v.id===t.observerId),b=state.units.find(v=>v.id===t.targetId);return U.rerollOptions(a,b,t.support.kind,{skillUsed:t.skillUsed,commandTokens:state.commandTokens[a.team]}).map(r=>({...r,key:r.id,label:r.name+' · WIP '+r.sv+(r.cost?' · 消耗 1 指挥令':'' )}));}
function applySupportRoll(t){const d=t.support,a={...state.units.find(v=>v.id===d.actorId),...d.actorPoint},b=state.units.find(v=>v.id===d.targetId);if(!t.valid){t.success=false;log(a.name+' '+ACTION_NAMES[d.kind]+'：未满足要求，按待机处理，不掷骰。');return;}const result=U.resolve(a,b,d.kind,d.mode,{die:t.dice[0],sv:t.sv});if(result.applied){Object.assign(b,result.target);t.success=result.success;log(`${a.name} ${ACTION_NAMES[d.kind]}：${result.success?'成功':result.removed?'失败，目标移除':result.damage?'失败，目标再受 1 伤':'失败，状态不变'}。`);}}
function prepareSupportEffects(){const o=state.order;if(o.supportPrepared)return;o.supportPrepared=true;if(o.hackSupport){const d=o.hackSupport,rr=H.resolveSupport(state.units,d.actorId,d.program,{targetId:d.targetId,troopType:d.troopType,terrain,repeaters:selected().hackingRepeaters||[],route:{kind:'autoFriendly'}});if(rr.can)state.units=rr.units;log('黑客支援：'+(rr.can?'已生效':rr.reason+'，转为待机'));}for(const d of o.supports||[]){const u=state.units.find(v=>v.id===d.actorId);if(d.kind==='reload'){const result=D.reload({...u,x:d.actorPoint.x,y:d.actorPoint.y,z:d.actorPoint.z},state.units);if(result.can)Object.assign(u,{spentWeapons:result.unit.spentWeapons,states:result.unit.states});log(u.name+' 装填：'+(result.can?'恢复可装填装备次数':result.reason+'，按待机处理'));}if(d.kind==='deployable'){d.route=d.reactive?[d.actorPoint]:structuredClone(declaredPath());const check=D.placement(d.actorPoint,d.itemId,d.point,{route:d.route,reactive:d.reactive,units:[...state.units,...state.hvts],terrain,orderId:o.orderId,templates,intuitive:d.intuitive});if(check.error?.includes('其他单位重叠')){const prior=state.units.map(v=>({...v,...d.declarationUnits?.find(n=>n.id===v.id)})),earlier=D.placement(d.actorPoint,d.itemId,d.point,{route:d.route,reactive:d.reactive,units:[...prior,...state.hvts],terrain,orderId:o.orderId,templates,intuitive:d.intuitive});if(!earlier.error)check.error='';}d.valid=!check.error;d.error=check.error;if(check.error)log(u.name+' 放置失败：'+check.error+'；使用次数已消耗。');}}}
