function targetlessControls(){const o=state.order,u=selected(),ids=Z.available(u);o.zoneWeapon=ids.includes(o.zoneWeapon)?o.zoneWeapon:ids[0];const w=Z.WEAPONS[o.zoneWeapon];return `<h3 class="paneltitle">${o.speculative?'推测射击 · 整令':'主动轮第二项行动 · 投掷／发射'}</h3>${o.speculative?'':'<button id="backToSkills" class="wide">← 返回行动选择</button>'}<label class="field">携带的武器<select id="zoneWeapon">${ids.map(id=>`<option value="${id}" ${o.zoneWeapon===id?'selected':''}>${Z.WEAPONS[id].name}${Z.WEAPONS[id].capacity?' · 剩余 '+D.remaining(u,id):''}</option>`).join('')}</select></label>${w?.doubleShot&&!o.speculative&&D.remaining(u,o.zoneWeapon)===2?`<label><input type="checkbox" id="zoneDouble" ${o.zoneDouble?'checked':''}>Double Shot：B2，同时消耗两次</label>`:''}${surfaceHTML()}${!o.speculative?`<label class="field">沿路发射位置<input id="supportPoint" type="range" min="0" max="${E.samplePath(declaredPath(),.15).length-1}" value="${o.shotIndex}"></label>`:''}<p class="stagePrompt">点击地图选择落点。确认前只显示定位十字，不显示射程或圆模板。</p><p class="helper">${o.speculative?'整令，B1，−6 加距离修正，可无视线抛射。地图建筑按可绕过的独立实体处理，暂不模拟封闭室内抛射。':'普通投射需要看见落点；ARO 还必须看见主动单位。'}${w?.zone?'烟雾宣告后展示待定模板，尚不阻挡本命令视线。':'部署物检定成功后在命令结束放置。迪斯科球为普通检定，不能抵消来袭射击。'}</p><button id="declareTargetless" class="primary wide" ${o.zonePoint?'':'disabled'}>确认${o.speculative?'整令推测射击':'投射'}宣告</button>`;}
