function activateBallControls(){const u=selected(),balls=state.units.filter(v=>v.deployableKind==='discoBall'&&v.team===u.team&&S.active(v));return `<h3 class="paneltitle">激活友方迪斯科球</h3><button id="backToSkills" class="wide">← 返回行动选择</button><label>友方球<select id="ballTarget">${balls.map(b=>`<option value="${b.id}">${b.name} (${b.x.toFixed(1)}, ${b.y.toFixed(1)})</option>`).join('')}</select></label><label class="field">沿路使用位置<input id="supportPoint" type="range" min="0" max="${E.samplePath(declaredPath(),.15).length-1}" value="${state.order.shotIndex}"></label><p class="helper">仅主动短技能；需要 Deactivator。球须在视线或控制区内，WIP+3 与消除器距离修正；命令结束开启 Eclipse。</p><button id="activateBall" class="primary wide" ${balls.length?'':'disabled'}>宣告激活</button>`;}
