function startPreparedGame(){state.tacticalWindow=true;O.refresh(state,0);O.refresh(state,1);I.beginTurn(state);state.selected=state.units.find(u=>u.team===state.team&&S.onTable(u))?.id||state.units.find(u=>u.team===state.team).id;log('部署完成，'+(state.team?'蓝':'红')+'方开始第一回合。');}
