function bindDeploymentSkills(){if(!$('setDeployState'))return;const u=selected();if($('terrainChoice'))$('terrainChoice').onchange=e=>{u.terrainChoice=e.target.value;u.deploymentReviewed=false;render();};if($('infiltrationReturn'))$('infiltrationReturn').onclick=()=>{const r=E.radius(u),y=u.deploymentSide==='north'?r:48-r,points=Array.from({length:95},(_,i)=>({x:r+i*.5,y,z:0})),p=points.find(p=>!Q.deploymentError(u,p,state.units,terrain,state.objectives));if(!p){toast('己方底边没有可用位置，请选择侧边');return;}Object.assign(u,p);render();};if($('infiltrationAttempt'))$('infiltrationAttempt').onchange=e=>{u.infiltrationAttempt=e.target.checked;u.deploymentReviewed=false;state.deployChoices=[];render();};if($('rollInfiltration'))$('rollInfiltration').onclick=()=>{const die=1+Math.floor(Math.random()*20),sv=P.infiltrationSV(u),success=U.passed(die,sv);u.infiltrationResolved=true;log(u.name+' 潜入：D20 '+die+' / PH−3 SV '+sv+' → '+(success?'成功':'失败，回己方桌边'));if(success)u.deploymentLocked=true;else{u.infiltrationFailed=true;u.deploymentReason='潜入失败，须回到己方桌边';u.infiltrationAttempt=false;u.deploymentLocked=false;u.states=u.states.filter(k=>!['camouflaged','hiddenDeployment','holomask'].includes(k));DX.failedSuperiorDeployment(state,u);}render();};$('deployState').value=u.offTable?'airborne':S.has(u,'hiddenDeployment')?'hidden':K.masked(u)?'holomask':K.marker(u)?'camo':'model';$('setDeployState').onclick=()=>changeDeploymentMode(u,$('deployState').value,$('holoAppearance')?.value);if($('deployProne'))$('deployProne').onchange=e=>{u.prone=e.target.checked;u.deploymentReviewed=false;render();};}

function extraControls(kind){const u=selected(),kit=kind!=='deactivator',targets=state.units.filter(v=>S.onTable(v)&&(kit?v.team===u.team:v.team!==u.team&&v.isDeployable));return `<h3>${ACTION_NAMES[kind]} · 主动轮短技能</h3><button id="backToSkills">← 返回行动选择</button><label>目标<select id="extraTarget">${targets.map(v=>`<option value="${v.id}">${safeText(v.name)}</option>`).join('')}</select></label>${kit?'<label>方式<select id="extraMode"><option value="ranged">远程投射 · BS 命中后 PH 检定</option><option value="contact">轮廓接触 · 直接 PH 检定</option></select></label>':''}<p>宣告前不测距。医疗包、维修包和拆除器不能用于 ARO；恢复在本命令伤害前生效。</p><button id="declareSupport" class="primary wide" ${targets.length?'':'disabled'}>宣告${ACTION_NAMES[kind]}</button>`;}
function openExtraRolls(){const o=state.order,d=(o.supports||[]).find(d=>['medikit','gizmokit','deactivator'].includes(d.kind)&&!d.extraDone);if(!d)return false;const a={...state.units.find(n=>n.id===d.actorId),...d.actorPoint},b=state.units.find(n=>n.id===d.targetId),el=$('battle');const draw=()=>{const r=X.resolve(a,b,d.kind,{attackDice:d.attackDice||[],phDice:d.phDice||[],discard:d.attackDiscard,mode:d.mode,terrain});const label=r.needsDiscard?'射击已掷骰：选择 SD 弃骰':r.needsAttack?'投射命中检定':r.needsPH?'命中 '+r.hits+' 次 → 接受者 PH 检定':!r.can?'要求未满足 · 待机':r.success?'成功生效':'检定失败';el.innerHTML=`<h2>${ACTION_NAMES[d.kind]}</h2><h3>${safeText(a.name)} → ${safeText(b.name)}</h3><p class="stagePrompt">${label}</p><p>${safeText(r.reason||'')} ${r.needsAttack?'SV '+r.sv+' · '+(r.burst+r.sd)+' 颗'+(r.sd?'（弃'+r.sd+'）':''):r.needsPH?'PH '+r.ph+' · '+r.phCount+' 颗':''}</p><div class="diceRow">${[...(d.attackDice||[]),...(d.phDice||[])].map(n=>'<span class="die"><strong>'+n+'</strong></span>').join('')}</div>${r.needsDiscard?'<fieldset><legend>SD 弃骰：选 '+r.sd+' 颗</legend>'+(d.attackDice||[]).map((n,i)=>'<label><input type="checkbox" data-extra-discard="'+i+'" '+((Array.isArray(d.attackDiscard)?d.attackDiscard:[d.attackDiscard]).includes(i)?'checked':'')+'>第'+(i+1)+'颗：'+n+'</label>').join('')+'</fieldset>':''}<button id="extraRoll" class="primary wide" ${r.needsDiscard?'disabled':''}>${r.needsAttack?'掷命中骰':r.needsPH?'掷 PH 骰':'确认结果 → 继续同时结算'}</button><p>这是装备恢复检定，不进入过保阶段。</p>`;el.querySelectorAll('[data-extra-discard]').forEach(input=>input.onchange=()=>{d.attackDiscard=[...el.querySelectorAll('[data-extra-discard]:checked')].map(n=>+n.dataset.extraDiscard);draw();});$('extraRoll').onclick=()=>{if(r.needsAttack||r.needsPH){const key=r.needsAttack?'attackDice':'phDice',count=r.needsAttack?r.burst+r.sd:r.phCount;d[key]=Array.from({length:count},()=>1+Math.floor(teachingRng()()*20));save();$('extraRoll').disabled=true;el.querySelector('.diceRow').classList.add('rolling');setTimeout(draw,800);}else{if(r.applied)Object.assign(b,r.target);d.extraDone=true;log(a.name+' '+ACTION_NAMES[d.kind]+'：'+label+'；骰 '+(d.attackDice||[]).join(',')+' / PH '+(d.phDice||[]).join(','));save();startDice();}};};draw();if(!el.open)el.showModal();el.oncancel=e=>e.preventDefault();return true;}

function bindAirborne(){document.querySelectorAll('[data-evo]').forEach(b=>b.onclick=()=>{const d=state.order.airborne,id=b.dataset.evo;if(d.decisions?.[id])return;if(b.dataset.choice==='use'){const r=H.resolveSupport(state.units,id,'controlledJump',{reactive:true,trigger:'combatJump'});if(!r.can){toast(r.reason);return;}state.units=r.units;}d.decisions??={};d.decisions[id]=b.dataset.choice;if(d.evos.every(id=>d.decisions[id])){d.aroPending=false;d.aroChecked=true;}render();});document.querySelectorAll('[data-airborne]').forEach(b=>b.onclick=()=>{const u=selected();if(state.order||u.team!==state.team||!AIR.availableActions(u).includes(b.dataset.airborne))return;const before=JSON.stringify(state);checkpoint();state.order={actor:u.id,orderId:++state.orderSerial,before,step:'airborne',firstKind:'airborne',activeSkill:'idle',idle:true,path:[{x:u.x,y:u.y,z:u.z||0}],reactions:{},weapon:u.weapon,modeId:F.ARMS[u.weapon].modes[0].id,shotIndex:0,airborne:{action:b.dataset.airborne}};render();});if($('confirmAirborne'))$('confirmAirborne').onclick=()=>{const o=state.order,d=o.airborne,u=selected(),opts={units:[...state.units,...state.hvts.map(h=>({...h,team:-1,states:[]}))],terrain,objectives:state.objectives,templates};if(!d.failed){const c=AIR.validateLanding(u,d.point,d.action,opts);if(!c.can){toast(c.reason);return;}d.landing=structuredClone(d.point);}if(d.action==='combatJump'&&d.die===undefined&&!d.aroChecked){d.evos=state.units.filter(v=>v.team!==u.team&&H.supportActions(v,{reactive:true,trigger:'combatJump'}).some(p=>p.id==='controlledJump')).map(v=>v.id);if(d.evos.length){d.aroPending=true;render();return;}d.aroChecked=true;}if(d.action==='combatJump'&&d.die===undefined){d.die=1+Math.floor(Math.random()*20);save();const r=AIR.resolve(u,d.landing,d.action,{...opts,die:d.die,controlledJumpMod:H.controlledJumpMod(u,state.units)});if(r.fallbackPending){d.failed=true;d.point=null;}render();return;}const r=AIR.resolve(u,d.landing,d.action,{...opts,die:d.die,controlledJumpMod:H.controlledJumpMod(u,state.units),fallback:d.failed?d.point:undefined});if(!r.applied){toast(r.reason||'请选择合法入场点');return;}Object.assign(u,r.unit);d.explosion=r.explosion;o.path=[{x:u.x,y:u.y,z:u.z||0}];o.step='aro1';collectReactions(1);for(const [id,choice] of Object.entries(d.decisions||{}))if(choice==='use')o.reactions[id]={id,wave:1,action:'controlledJump',lof:false,points:[]};for(const id of d.explosion?.hits||[])if(!o.reactions[id])o.reactions[id]={id,affected:true,lof:F.canSee(state.units.find(n=>n.id===id),u,terrain),wave:1,action:'',weapon:null};log(u.name+' '+AIR.LABELS[d.action]+'入场'+(d.die?'：骰 '+d.die:''));render();};}

function hackingSupportControls(){const o=state.order,u=selected(),long=M.isLong(o.firstKind),programs=H.supportActions(u).filter(p=>p.id!=='zeroPain'&&(long?p.id===o.program:p.skill==='short'));o.program??=programs[0]?.id;return `<h3>黑客支援 · ${long?'整令':'短技能'}</h3>${!long?'<button id="backToSkills">← 返回</button>':''}<label>程序<select id="supportProgram">${programs.map(p=>`<option value="${p.id}" ${p.id===o.program?'selected':''}>${p.name}</option>`).join('')}</select></label><label>友方 REM<select id="programTarget">${state.units.filter(n=>n.team===u.team&&n.type==='REM'&&S.onTable(n)).map(n=>`<option value="${n.id}">${safeText(n.name)}</option>`).join('')}</select></label><label>仙尘选择兵种<select id="programType">${['HI','REM','TAG','VH'].map(k=>`<option>${k}</option>`).join('')}</select></label><p>程序按自己的设备提供。辅助射击／强化反应须在黑客范围；网络伪装须处于敌方视线外。宣告前不测距，结算时检查。</p><button id="declareProgram" class="primary wide">宣告程序 → ARO</button>`;}
function bindHackingSupport(){if($('supportProgram'))$('supportProgram').onchange=e=>{state.order.program=e.target.value;save();};if($('declareProgram'))$('declareProgram').onclick=()=>{const o=state.order,u=selected(),id=$('supportProgram').value,targetId=$('programTarget')?.value,troopType=$('programType')?.value,sp=H.supportSpec(u,id,{target:state.units.find(n=>n.id===targetId),troopType,units:state.units,terrain,measure:false});if(!sp.can){toast(sp.reason);return;}o.hackSupport={actorId:u.id,program:id,targetId,troopType};o.idle=true;o.activeSkill='supportware';K.reveal(u);collectReactions(M.isLong(o.firstKind)?1:2);o.step=M.isLong(o.firstKind)?'aro1':'aro2';render();};}

function deploymentExtraHTML(u){const actions=DX.actions(state,u);if(!actions.length&&!state.deploymentTool)return '';const d=state.deploymentTool;return '<h3>部署技能</h3>'+actions.map(a=>a.id==='minelayer'?'<label>布雷者装备<select id="minelayerItem">'+a.items.map(k=>'<option value="'+k+'">'+D.ITEMS[k].name+'</option>').join('')+'</select></label><button id="planMinelayer">指定布雷位置</button>':'<button id="planDecoy">指定 '+a.count+' 个诱饵位置</button>').join('')+(d?'<p class="stagePrompt">点击地图指定位置；已选 '+d.points.length+' 个。测量确认后真实模型位置固定。</p><button id="confirmDeploymentExtra">确认部署技能</button><button id="cancelDeploymentExtra">取消选点</button>':'');}
function bindDeploymentExtras(){if($('planMinelayer'))$('planMinelayer').onclick=()=>{state.deploymentTool={kind:'minelayer',actorId:selected().id,itemId:$('minelayerItem').value,points:[]};render();};if($('planDecoy'))$('planDecoy').onclick=()=>{state.deploymentTool={kind:'decoy',actorId:selected().id,points:[]};render();};if($('cancelDeploymentExtra'))$('cancelDeploymentExtra').onclick=()=>{delete state.deploymentTool;render();};if($('confirmDeploymentExtra'))$('confirmDeploymentExtra').onclick=()=>{const d=state.deploymentTool,u=state.units.find(n=>n.id===d.actorId);if(!d.points.length){toast('先点击地图选择位置');return;}const r=d.kind==='minelayer'?DX.placeMine(state,u,d.itemId,d.points.at(-1),{terrain,templates}):DX.placeDecoys(state,u,d.points,{terrain});if(r.error){toast(r.error);render();return;}delete state.deploymentTool;render();};}

function orderPartners(u){return [...new Map([...PER.partners(u,state.units),...FT.partners(u,state.units)].map(v=>[v.id,v])).values()];}
function startLinkedMove(){const o=state.order,key=o.secondMove?'second':'first',done=Array.isArray(o.linkedDone?.[key])?o.linkedDone[key]:o.linkedDone?.[key]?orderPartners(selected()).map(v=>v.id):[],v=orderPartners(selected()).find(v=>!done.includes(v.id));if(!v||!['move','superjump','superlong','jump','climb','climbplus'].includes(o.moveKind))return false;const unsupported=!S.allowed(v,'move')||o.moveKind==='superjump'&&!v.superJump||o.moveKind==='superlong'&&!v.superJump||o.moveKind==='climbplus'&&!v.climbingPlus;o.linkedMove={id:v.id,key,moveKind:unsupported?'idle':o.moveKind,firstKind:o.firstKind,secondMove:o.secondMove,stance:'keep',terrainStopped:!!o.linkedTerrainStopped?.[v.id],path:[{x:v.x,y:v.y,z:v.z||0}],cost:0};o.step='linkedMove';render();return true;}

function addLinkedPoint(p){const o=state.order,l=o.linkedMove,v=state.units.find(n=>n.id===l.id);if(l.moveKind==='idle'||!S.allowed(v,'move')){toast('该成员状态不允许移动，本技能按待机处理');return;}let plan;if(M.isJump(l.moveKind))plan=M.planJump(v,l,p,state.units,terrain);else if(M.isClimb(l.moveKind))plan=M.autoClimb(v,p,M.budget(v,l),terrain,state.units);else{const nearest=M.nearestReachable(v,l,M.snapPassage(v,{...p,z:v.z||0},terrain)||{...p,z:v.z||0},state.units,terrain,{finish:false});plan=nearest.error?nearest:{points:nearest.path,cost:nearest.cost};}if(plan.error){toast(plan.error);return;}const draft={...l,path:plan.points,cost:plan.cost};const bad=M.validate(v,draft,state.units,terrain,M.isJump(l.moveKind)?plan.jumpHasLanding!==false:M.isClimb(l.moveKind));if(bad){toast(bad);return;}Object.assign(l,draft,{jumpWaypoints:plan.jumpWaypoints,jumpHasLanding:plan.jumpHasLanding});render();}
function finishLinkedMove(skip=false){const o=state.order,l=o.linkedMove,v=state.units.find(n=>n.id===l.id);if(skip){l.path=[l.path[0]];l.cost=0;delete l.jumpWaypoints;delete l.jumpHasLanding;}const bad=M.validate(v,l,state.units,terrain);if(bad){toast(bad);return;}if(TR.stops(v,l.path)){o.linkedTerrainStopped??={};o.linkedTerrainStopped[v.id]=true;}Object.assign(v,l.path.at(-1));v.prone=E.endingProne(v,l.stance);o.linkedPaths??={};o.linkedPaths[v.id]=[...(o.linkedPaths[v.id]||[]),...l.path];o.linkedDone??={};if(!Array.isArray(o.linkedDone[l.key]))o.linkedDone[l.key]=[];o.linkedDone[l.key].push(v.id);triggerMines(v,l.path);delete o.linkedMove;confirmMove();}

function maskOptionsHTML(u){return u.holomask?'<label>全息外观（同分军／同S）<select id="holoAppearance">'+u.holoOptions.map(v=>'<option value="'+v.ref+'" '+(u.holoAppearance?.ref===v.ref?'selected':'')+'>'+safeText(v.name+' · '+v.weapons)+'</option>').join('')+'</select></label>':'';}

function changeDeploymentMode(u,v,ref){if(!P.editable(state,u)){toast('当前模型的部署方式已固定');return;}if(u.infiltrationFailed&&v!=='model'){toast('潜入失败后只能以模型部署');return;}u.states=u.states.filter(k=>!['camouflaged','hiddenDeployment','holomask'].includes(k));u.offTable=v==='airborne';u.airborneOrderAvailable=u.offTable;if(v==='holomask')K.enterMask(u,ref||u.holoAppearance?.ref||u.holoOptions?.[0]?.ref);if(v==='camo')K.enterCamo(u);if(v==='hidden')u.states.push('hiddenDeployment');u.deploymentReviewed=false;state.deployChoices=[];render();}

function fireteamBonusText(n){return ['同组共用命令',n>=2?'射击 +1 SD':'',n>=3?'发现 +3 / 闪避 +1':'',n>=4?'射击属性 +1':'',n>=5?'第六感':''].filter(Boolean).join(' · ');}
function aroSkill(r){if(r.ftCCSupport)return '近战';if(r.action==='attack'){const m=F.weaponMode(r.weapon,r.modeId);return m.kind==='hack'?'黑客':m.kind==='cc'?'近战':'射击';}return r.action==='targetless'?'射击':({dodge:'闪避',reset:'重置',zeroPain:'黑客',controlledJump:'黑客',deployable:'放置部署物',reload:'装填',discover:'发现'})[r.action]||r.action;}
function fireteamAROHTML(){const o=state.order;return FT.aroGroups(state,o.reactions,aroSkill).map(g=>'<div class="ft-aro"><b>'+safeText(g.f.label)+' · 组 ARO</b><p>'+Object.entries(g.counts).map(([k,n])=>k+' '+n+'人').join(' / ')+'</p>'+(g.majority?'<p>多数技能：'+g.majority+'。其他技能成员会脱组；队长异类则解散。</p>':'<label>没有绝对多数，请选择组技能<select data-ft-aro="'+g.f.id+'"><option value="">请选择</option>'+Object.keys(g.counts).map(k=>'<option '+(o.ftAroChoices?.[g.f.id]===k?'selected':'')+'>'+k+'</option>').join('')+'</select></label>')+'</div>').join('');}
function packFireteam(proposal){const us=proposal.ids.map(id=>state.units.find(u=>u.id===id));if(us.some(u=>!P.editable(state,u)))throw Error('只有当前可调整部署的成员能自动靠拢；已固定／保留模型不能移动');const before=structuredClone(us),leader=us.find(u=>u.id===proposal.leaderId);try{for(const u of us.filter(u=>u!==leader)){const points=[];for(let y=Math.max(E.radius(u),leader.y-7);y<=Math.min(48-E.radius(u),leader.y+7);y+=.6)for(let x=Math.max(E.radius(u),leader.x-7);x<=Math.min(48-E.radius(u),leader.x+7);x+=.6){const p={x,y,z:leader.z||0};if(FT.coherent({...u,...p},leader)&&!DP.positionError(state,u,p,terrain))points.push(p);}points.sort((a,b)=>E.dist(a,leader)-E.dist(b,leader));if(!points.length)throw Error('当前掩体附近空间不足以部署完整队形');Object.assign(u,points[0],{deploymentReviewed:false});}}catch(e){for(const old of before)Object.assign(state.units.find(u=>u.id===old.id),old);throw e;}}
function renderFireteams(){let el=$('fireteamManager');if(!el){el=document.createElement('section');el.id='fireteamManager';$('flowbar').before(el);}const open=el.querySelector('details')?.open||false;const fs=(state.fireteams||[]).filter(f=>!f.cancelled);el.innerHTML='<details '+(open?'open':'')+'><summary>火力组管理 · '+fs.length+' 组'+(fs.length?' · '+fs.map(f=>f.label+' L'+f.level).join(' / '):'')+'</summary><p>部署时免费创建并检查一致性，随后位置固定。局中创建每组1枚指挥令，仅本方主动轮命令间；双方回合均可在花命令前免费解散。等级按同源成员计算。</p>'+manualFireteamHTML()+[0,1].map(t=>'<button data-ft-random="'+t+'" '+(state.order||state.phase==='play'&&state.team!==t||state.phase==='deploy'&&P.deploymentTeam(state)!==t||!['deploy','play'].includes(state.phase)?'disabled':'')+'>'+ (t?'◆ 蓝':'▲ 红')+' 随机合法组队'+(state.phase==='deploy'?'并靠拢部署':'（每组1CT）')+'</button>').join('')+fs.map(f=>'<article class="ft-card"><b>'+safeText(f.label)+' · '+f.members.length+'人 · L'+f.level+'</b><p>'+fireteamBonusText(f.level)+'</p><div>'+FT.members(state,f).map(u=>'<button data-ft-select="'+u.id+'">'+(u.ftLeader?'★ ':'')+safeText(u.name)+'</button>').join('')+'</div><button data-ft-cancel="'+f.id+'" '+(state.order?'disabled':'')+'>免费解散（双方回合可用）</button></article>').join('')+'<div id="ftResult" role="status">'+safeText(state.ftMessage||'编组只使用当前军表的精确配置及官方编组表。')+'</div><button id="ftLesson">打开真实 MO 火力组演练</button></details>';el.querySelectorAll('[data-ft-select]').forEach(b=>b.onclick=()=>selectUnit(b.dataset.ftSelect));el.querySelectorAll('[data-ft-cancel]').forEach(b=>b.onclick=()=>{if(state.order)return;checkpoint();for(const msg of FT.cancel(state,b.dataset.ftCancel))log(msg);FT.sync(state);render();});el.querySelectorAll('[data-ft-random]').forEach(b=>b.onclick=()=>{if(state.order)return;const t=+b.dataset.ftRandom;try{checkpoint();let total=0;while(total<Math.floor(state.units.length/2)){let choices=FT.proposals(state,t,{coherency:state.phase!=='deploy'});if(state.phase==='deploy')choices=choices.filter(p=>p.ids.every(id=>P.editable(state,state.units.find(u=>u.id===id))));if(!choices.length)break;const max=Math.max(...choices.map(p=>p.ids.length));choices=choices.filter(p=>p.ids.length===max);const p=choices[Math.floor(Math.random()*choices.length)];p.leaderId=p.ids[Math.floor(Math.random()*p.ids.length)];if(state.phase==='deploy')packFireteam(p);const f=FT.create(state,p);log('创建 '+f.label+'：'+FT.members(state,f).map(u=>u.name).join('、')+'；同源L'+f.level);total++;}state.ftMessage=total?'已创建 '+total+' 个合法火力组。':t===1?'当前玉京军表没有合法组合；孤胆／龙牙不在其编组表，不能自动凑队。':'没有可创建的合法且一致的组合；请检查战斗组、部署阶段、同队距离及指挥令。';}catch(e){state.ftMessage=e.message;}render();$('fireteamManager').querySelector('details').open=true;});$('ftLesson').onclick=()=>loadLesson('fireteam30');bindManualFireteam();}

function settleFireteamCC(){const o=state.order;for(const f of state.fireteams||[]){if(f.cancelled)continue;const groups={};for(const u of FT.members(state,f)){const r=o.reactions[u.id];if(r?.action==='attack'&&F.weaponMode(r.weapon,r.modeId).kind==='cc')(groups[r.targetId||selected().id]??=[]).push(r);}for(const [id,rs] of Object.entries(groups)){const winner=rs.find(r=>r.id===f.leaderId)||rs[0],target=state.units.find(n=>n.id===id),roller=state.units.find(n=>n.id===winner.id);roller.ccSupport=state.units.filter(n=>n.id!==roller.id&&n.team===roller.team&&S.onTable(n)&&S.active(n)&&!S.has(n,'immA')&&!S.has(n,'immB')&&E.edgeDistance(n,target)<=.025&&!['dodge','none','reset'].includes(o.reactions[n.id]?.action)).length;for(const r of rs)if(r!==winner){r.action='ccSupport';r.ftCCSupport=true;}}}}


function fireteamDraft(){const team=state.phase==='deploy'?(P.deploymentTeam(state)??state.team):state.team;if(!ftDraft||ftDraft.units!==state.units.map(u=>u.id).join('|'))ftDraft={units:state.units.map(u=>u.id).join('|'),team,ids:[],leaderId:'',tableIndex:0,type:'CORE'};return ftDraft;}
function manualFireteamHTML(){const d=fireteamDraft(),us=state.units.filter(u=>u.team===d.team&&u.armyRef&&!u.peripheral),data=FT.chart(us[0]||{}),tables=(data?.teams||[]).flatMap((t,i)=>t.type.map(type=>({i,type,name:t.name})));if(!tables.some(t=>t.i===d.tableIndex&&t.type===d.type)&&tables.length)Object.assign(d,{tableIndex:tables[0].i,type:tables[0].type});d.ids=d.ids.filter(id=>us.some(u=>u.id===id));if(!d.ids.includes(d.leaderId))d.leaderId=d.ids[0]||'';const r=FT.preview(state,d);return `<fieldset class="ft-builder"><legend>手动创建／重组</legend><div class="ft-fields"><label>军队<select id="ftTeam"><option value="0" ${d.team===0?'selected':''}>▲ 红队</option><option value="1" ${d.team===1?'selected':''}>◆ 蓝队</option></select></label><label>编组表与类型<select id="ftTable">${tables.length?tables.map(t=>`<option value="${t.i}:${t.type}" ${t.i===d.tableIndex&&t.type===d.type?'selected':''}>${safeText(t.name)} · ${t.type}</option>`).join(''):'<option value="">此军队没有可用编组表</option>'}</select></label></div><div class="ft-members">${us.map(u=>{const reason=FT.unavailableReason(u,state.units)||(!FT.assignment(u,data?.teams[d.tableIndex])?'此配置不在所选编组表':''),old=FT.find(state,u);return `<label class="ft-member"><input type="checkbox" data-ft-member="${u.id}" ${d.ids.includes(u.id)?'checked':''}><span>${safeText(u.name)} <small>G${O.group(u)} · ${safeText(u.en)}${old?' · 现属 '+safeText(old.label):''}</small>${reason?'<em>'+safeText(reason)+'</em>':''}</span></label>`;}).join('')||'<p>请先导入官方军表。</p>'}</div><label>指定队长<select id="ftLeader">${d.ids.length?d.ids.map(id=>{const u=us.find(u=>u.id===id);return `<option value="${id}" ${id===d.leaderId?'selected':''}>${safeText(u.name)} · G${O.group(u)}</option>`;}).join(''):'<option value="">先选择成员</option>'}</select></label><div id="ftValidation" class="ft-validation ${r.valid?'valid':'invalid'}" role="status" aria-live="polite"><b>${r.valid?'✓ 编组合法':'尚不能创建'} · 已选 ${d.ids.length} 人</b>${r.reasons.length?'<ul>'+r.reasons.map(x=>'<li>'+safeText(x)+'</li>').join('')+'</ul>':''}<p>${r.valid?'加成':'预计加成（须先满足全部条件）'}：${r.level?'L'+r.level+' · '+fireteamBonusText(r.level):'选择成员后计算'}</p><p>${r.cost?'确认消耗 1 枚指挥令':'部署阶段免费'}；按当前落点检查队长8″一致性，手动创建不会移动模型。</p>${r.affected.length?'<p>确认后解散旧组：'+r.affected.map(f=>safeText(f.label)).join('、')+'；未选入新组的原成员成为独立单位。</p>':''}</div><button id="ftCreate" class="primary" ${r.valid?'':'disabled'}>${r.affected.length?'确认重组':'创建火力组'}${r.cost?' · 1CT':' · 免费'}</button><button id="ftClear">清空选择</button>${state.phase==='deploy'?'<button id="ftArrange" '+(!state.order&&d.ids.length>1&&d.ids.every(id=>P.editable(state,state.units.find(u=>u.id===id)))?'':'disabled')+'>靠拢所选成员（调整部署）</button>':''}</fieldset>`;}
function bindManualFireteam(){const d=fireteamDraft(),draw=()=>{renderFireteams();$('fireteamManager').querySelector('details').open=true;};$('ftTeam').onchange=e=>{d.team=+e.target.value;d.ids=[];d.leaderId='';draw();};$('ftTable').onchange=e=>{const [i,t]=e.target.value.split(':');d.tableIndex=+i;d.type=t;draw();};document.querySelectorAll('[data-ft-member]').forEach(input=>input.onchange=()=>{const id=input.dataset.ftMember;d.ids=input.checked?[...d.ids,id]:d.ids.filter(x=>x!==id);draw();});$('ftLeader').onchange=e=>{d.leaderId=e.target.value;draw();};$('ftClear').onclick=()=>{d.ids=[];d.leaderId='';draw();};if($('ftArrange'))$('ftArrange').onclick=()=>{try{checkpoint();packFireteam(d);render();$('fireteamManager').querySelector('details').open=true;}catch(e){toast(e.message);}};$('ftCreate').onclick=()=>{const r=FT.preview(state,d);if(!r.valid){draw();return;}try{checkpoint();const f=FT.reform(state,d);state.ftMessage='已手动'+(r.affected.length?'重组':'创建')+' '+f.label+' · 队长 '+state.units.find(u=>u.id===f.leaderId).name+' · L'+f.level;log(state.ftMessage+(r.cost?' · 消耗1CT':' · 部署免费'));d.ids=[];d.leaderId='';render();$('fireteamManager').querySelector('details').open=true;}catch(e){toast(e.message);draw();}};}

function regularPoolHTML(team,group){const count=Math.max(0,Math.floor(O.pools(state,team)[group]||0)),waiting=['pregame','deploy'].includes(state.phase),label=waiting?'正规命令 · 开局生成':'剩余正规命令 '+count;return `<div class="roster-order-pool team-${team}" aria-label="${team?'蓝':'红'}队战斗组${group}，${label}"><div class="roster-order-label"><b>G${group}</b><span>正规命令</span><strong>${waiting?'—':count}</strong></div><div class="regular-order-icons" aria-hidden="true">${waiting?'<small>开始游戏时生成</small>':count?Array.from({length:count},()=>'<span class="regular-order-token" title="正规命令"><svg viewBox="0 0 20 20" focusable="false"><circle cx="10" cy="10" r="8"/><path d="M6 6h8v8H6zM10 3v3M10 14v3M3 10h3M14 10h3"/></svg></span>').join(''):'<small>已耗尽</small>'}</div></div>`;}

function renderMode(){const tutorial=state.appMode==='tutorial',m=Q.MISSIONS[state.missionId||'hardlock'];document.body.dataset.appMode=state.appMode||'legacy';document.querySelector('.roster h1').innerHTML=tutorial?'教学演示<span>FIELD ACADEMY</span>':safeText(m.name)+'<span>'+m.en+'</span>';document.querySelector('.roster .intro').textContent=tutorial?'固定敌我配置 · N5.3 / FAQ v0.1':'ITS18 · 300点级 · 12″部署区 · 三轮';document.querySelector('.score div:first-child small').textContent='▲ 红队';document.querySelector('.score div:last-child small').textContent='◆ 蓝队';$('sectorbar').hidden=tutorial&&state.lesson!=='console';document.querySelector('.score').hidden=tutorial;$('scoreLabel').hidden=tutorial;$('armyImportBtn').hidden=tutorial;$('tutorialCatalogBtn').hidden=!tutorial;document.querySelector('.lessonPicker').hidden=state.appMode==='match';document.querySelector('.scenarioButtons').hidden=!!state.appMode;}
